---
export const prerender = false;

import Layout from '@/layouts/base.astro';
import { findLevel, parseMapMoveResponses } from '@/lib/quiz-engine';
import MapMoveResults from '@/lib/quiz-engine/components/MapMoveResults.astro';
import { getEntry, render } from 'astro:content';

const { slug } = Astro.params;
const entry = await getEntry('quizzes', slug!);
if (!entry) {
  return new Response(null, { status: 404, statusText: 'Not found' });
}

const data = entry.data;
const params = Astro.url.searchParams;
const resultStyle = data.resultStyle ?? 'band';

// --- map-move -------------------------------------------------------------
// The taker's answers ride in the `a` param; rebuild the map from them. If it's
// missing, send them back to the quiz rather than showing an empty result.
const mapMoveResponses =
  resultStyle === 'map-move' ? parseMapMoveResponses(params) : {};
if (
  resultStyle === 'map-move' &&
  Object.keys(mapMoveResponses).length === 0
) {
  return Astro.redirect(`/quiz/${entry.id}/`);
}

// --- band -----------------------------------------------------------------
const totalRaw = params.get('total');
const maxRaw = params.get('max');
const level = params.get('level');
const total = totalRaw !== null ? parseInt(totalRaw, 10) : NaN;
const maxTotal = maxRaw !== null ? parseInt(maxRaw, 10) : NaN;

if (
  resultStyle === 'band' &&
  (Number.isNaN(total) || Number.isNaN(maxTotal) || !level)
) {
  return Astro.redirect(`/quiz/${entry.id}/`);
}

const overall =
  resultStyle === 'band' ? findLevel(total, data.overallLevels ?? []) : null;
const overallTitle = overall?.title ?? overall?.level ?? 'Your result';

const { Content } = await render(entry);
---

<Layout
  title={`${data.title} — Results`}
  description={data.description ?? data.title}
  includeCoursesCTA={false}
  noIndex={true}
>
  {
    resultStyle === 'map-move' ? (
      <div class="bg-quiz-page px-4 py-12 md:py-16">
        <MapMoveResults quiz={data} responses={mapMoveResponses} />
        <section class="mx-auto mt-10 max-w-170">
          <a
            href={`/quiz/${entry.id}/`}
            class="text-[13px] text-quiz-ink-muted hover:underline"
          >
            Take the quiz again
          </a>
        </section>
      </div>
    ) : (
      <div class="container mx-auto px-4 py-12 md:py-16">
        <section class="mx-auto mb-10 max-w-3xl text-center">
          <p class="mb-2 text-sm font-medium tracking-wide text-indigo-600 uppercase">
            Your result
          </p>
          <h1 class="mb-4 text-3xl font-bold text-gray-900 md:text-5xl">
            {overallTitle}
          </h1>
          <p class="mb-6 text-lg text-gray-700">
            You scored <strong>{total}</strong> out of <strong>{maxTotal}</strong>.
          </p>
          {data.resultsSubtitle ? (
            <p class="mx-auto max-w-2xl text-base/relaxed  text-gray-700 md:text-lg">
              {data.resultsSubtitle}
            </p>
          ) : null}
        </section>

        {/* TEMPORARY: remove once the mailing-list flow can deliver personalised result reports. */}
        <section class="mx-auto mb-8 max-w-3xl">
          <div
            class="rounded-md border-l-4 border-indigo-500 bg-indigo-50 p-4 text-gray-800"
            role="note"
          >
            <p>
              <strong>A quick note.</strong> This page is your result. Any link
              you save or revisit will land you right back here. We can't yet
              send you a personalised report by email, but watch your inbox for a
              deep dive on these failure modes followed by a short series of
              related emails.
            </p>
          </div>
        </section>

        <section class="mx-auto max-w-3xl">
          <div class="prose prose-blue prose-headings:scroll-mt-24 prose-strong:text-blue-900 max-w-none">
            <Content />
          </div>
        </section>

        <section class="mx-auto mt-12 max-w-3xl text-center">
          <a
            href={`/quiz/${entry.id}/`}
            class="inline-block rounded-md border border-indigo-600 px-5 py-2.5 text-base font-medium text-indigo-700 transition hover:bg-indigo-50"
          >
            Test your knowledge again
          </a>
        </section>
      </div>
    )
  }
</Layout>

