import { compile } from '@tailwindcss/node';
import fs from 'node:fs';
import path from 'node:path';

const root = process.cwd();
const BEFORE = '/tmp/src-full-before';

// compiler.build() is INCREMENTAL -- it accumulates candidates across calls.
// Reusing one compiler makes every list resolve against every class seen so
// far, which silently turns this check into a no-op. Fresh compiler each time.
async function buildCss(classes) {
  const c = await compile('@import "tailwindcss";', {
    base: root,
    onDependency: () => {},
  });
  return c.build(classes);
}

const theme = {};
for (const m of (await buildCss(['m-1'])).matchAll(/(--[\w-]+):\s*([^;]+);/g))
  theme[m[1]] = m[2].trim();

function resolveVars(v, locals, depth = 0) {
  if (depth > 12) return v;
  const next = v.replace(
    /var\((--[\w-]+)(?:,\s*([^()]*(?:\([^()]*\))?[^()]*))?\)/g,
    (_m, name, fb) => {
      const val = locals[name] ?? theme[name];
      return val !== undefined ? val : fb !== undefined ? fb : `var(${name})`;
    }
  );
  return next === v ? v : resolveVars(next, locals, depth + 1);
}

function normalize(value, locals) {
  let v = resolveVars(value, locals).replace(/\s+/g, ' ').trim();
  for (let i = 0; i < 8; i++) {
    const b = v;
    v = v.replace(
      /calc\(\s*([\d.]+)(rem|px|em)?\s*([*/])\s*([\d.]+)\s*\)/g,
      (_m, a, unit, op, n2) => {
        const n = op === '*' ? Number(a) * Number(n2) : Number(a) / Number(n2);
        return `${+n.toFixed(6)}${unit ?? ''}`;
      }
    );
    if (v === b) break;
  }
  return v.replace(/([\d.]+)rem\b/g, (_m, n) => `${+(Number(n) * 16).toFixed(4)}px`);
}

async function resolve(classes) {
  const css = await buildCss(classes);
  const i = css.indexOf('@layer utilities');
  if (i === -1) return {};
  let body = css.slice(i);
  // @property / @layer properties trail the utilities layer: registration
  // plumbing, present or absent purely by whether a --tw-* var was used.
  const p = body.indexOf('@property');
  if (p !== -1) body = body.slice(0, p);
  body = body.slice(body.indexOf('{') + 1);

  const raw = {};
  let media = 'base';
  const stack = [];
  const re = /@media([^{]+)\{|([^{}@]+)\{([^{}]*)\}|\}/g;
  let m;
  while ((m = re.exec(body))) {
    if (m[1]) {
      stack.push(media);
      media = m[1].trim();
    } else if (m[2]) {
      for (const d of m[3].split(';')) {
        const idx = d.indexOf(':');
        if (idx === -1) continue;
        (raw[media] ??= {})[d.slice(0, idx).trim()] = d.slice(idx + 1);
      }
    } else if (stack.length) media = stack.pop();
  }

  const baseLocals = Object.fromEntries(
    Object.entries(raw.base ?? {}).filter(([k]) => k.startsWith('--'))
  );
  const out = {};
  for (const [mq, decls] of Object.entries(raw)) {
    const locals = {
      ...baseLocals,
      ...Object.fromEntries(Object.entries(decls).filter(([k]) => k.startsWith('--'))),
    };
    for (const [prop, val] of Object.entries(decls))
      if (!prop.startsWith('--')) out[`${mq}|${prop}`] = normalize(val, locals);
  }
  for (const mq of Object.keys(raw)) {
    if (mq === 'base') continue;
    for (const [prop, val] of Object.entries(raw.base ?? {}))
      if (!prop.startsWith('--'))
        out[`${mq}|${prop}`] ??= normalize(val, baseLocals);
  }
  return out;
}

function classLists(src) {
  const lists = [];
  for (const m of src.matchAll(
    /(?:class|className|class:list)\s*=\s*(?:"([^"]*)"|'([^']*)'|\{?`([^`]*)`)/g
  ))
    lists.push(m[1] ?? m[2] ?? m[3]);
  for (const m of src.matchAll(/'([^'\n]{4,200})'/g)) lists.push(m[1]);
  for (const m of src.matchAll(/"([^"\n]{4,200})"/g)) lists.push(m[1]);
  const out = new Set();
  for (const raw of lists) {
    const t = raw
      .split(/\s+/)
      .filter(
        (x) =>
          /^[a-z0-9:./\[\]_!-]+$/i.test(x) &&
          /-|^(flex|grid|block|hidden|italic|underline|relative|absolute|fixed|sticky|truncate|uppercase)$/.test(x)
      );
    if (t.length) out.add(t.join(' '));
  }
  return out;
}

function walk(dir, acc = []) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, acc);
    else if (/\.(astro|tsx|jsx|ts|js|mjs|mdx)$/.test(e.name)) acc.push(p);
  }
  return acc;
}

const fp = (map) => JSON.stringify(Object.entries(map).sort());
let filesChanged = 0,
  changedLists = 0,
  identical = 0;
const suspect = [];

for (const beforePath of walk(BEFORE)) {
  const rel = path.relative(BEFORE, beforePath);
  const afterPath = path.join('src', rel);
  if (!fs.existsSync(afterPath)) continue;
  const b = fs.readFileSync(beforePath, 'utf8');
  const a = fs.readFileSync(afterPath, 'utf8');
  if (b === a) continue;
  filesChanged++;

  const before = classLists(b);
  const after = classLists(a);
  const bOnly = [...before].filter((x) => !after.has(x));
  const aOnly = [...after].filter((x) => !before.has(x));
  if (!bOnly.length) continue;

  const aMaps = [];
  for (const c of aOnly)
    aMaps.push({ c, map: await resolve(c.split(' ')), used: false });

  for (const bc of bOnly) {
    changedLists++;
    const bmap = await resolve(bc.split(' '));
    const hit = aMaps.find((x) => !x.used && fp(x.map) === fp(bmap));
    if (hit) {
      hit.used = true;
      identical++;
      continue;
    }
    const near = aMaps
      .filter((x) => !x.used)
      .map((x) => {
        const keys = new Set([...Object.keys(bmap), ...Object.keys(x.map)]);
        return { x, diffs: [...keys].filter((k) => bmap[k] !== x.map[k]) };
      })
      .sort((p, q) => p.diffs.length - q.diffs.length)[0];
    suspect.push({
      file: rel,
      before: bc,
      after: near?.x.c ?? '(no candidate)',
      diffs: (near?.diffs ?? []).slice(0, 4).map((k) => `${k}: ${bmap[k] ?? '(absent)'} -> ${near.x.map[k] ?? '(absent)'}`),
    });
  }
}

console.log(`files changed by --fix: ${filesChanged}`);
console.log(`rewritten class lists checked: ${changedLists}`);
console.log(`  behaviourally IDENTICAL: ${identical}`);
console.log(`  NOT identical: ${suspect.length}`);
for (const s of suspect) {
  console.log(`\n!! ${s.file}`);
  console.log(`   before: ${s.before}`);
  console.log(`   after : ${s.after}`);
  for (const d of s.diffs) console.log(`     ${d}`);
}

