import { Picture } from 'astro:assets';
import type { ImageMetadata } from 'astro';

interface Props {
  src: ImageMetadata;
  alt: string;
  caption?: string;
  align?: 'left' | 'right' | 'normal';
}

const { src, alt, caption, align = 'normal' } = Astro.props;

const floatStyle =
  align === 'left'
    ? 'float: left; margin-right: 1rem;'
    : align === 'right'
      ? 'float: right; margin-left: 1rem;'
      : '';
---

