    loading="lazy"
    formats={['avif', 'webp', 'jpg']}
    class="mx-auto"
    style={floatStyle}
  />
  {
    caption && (
      <figcaption
        class="t max-w-2xl text-center text-base italic"
        set:html={caption}
      />
    )
  }
</figure>

