export const prerender = true;

import clsx from 'clsx';
import ModalPopup from '@/components/global/modal-popup.astro';
import { SignupSource } from '@/constants/signup';
import Layout from '@/layouts/base.astro';
import TableOfContentsAccordian from '@/components/blog/table-of-contents-accordian';
import TableOfContents from '@/components/blog/table-of-contents.astro';

import Categories from '@/components/blog/categories.astro';
import LinkSidebar from '@/components/global/link-sidebar.astro';
import Author from '@/components/blog/author.astro';
import { getCollection, getEntry, render } from 'astro:content';

import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from '@/components/ui/breadcrumb';

export async function getStaticPaths() {
  const posts = await getCollection('blog');
  const showDrafts = process.argv.includes('--drafts');

  if (showDrafts) {
    return posts.map((post) => ({
      params: { id: post.id },
    }));
  } else {
    return posts
      .filter((post) => !post.data.draft)
      .map((post) => ({
        params: { id: post.id },
      }));
  }
}

const { id } = Astro.params;
const entry = await getEntry('blog', id);
if (!entry) {
  return new Response(null, {
    status: 404,
    statusText: 'Not found',
  });
}

const categoriesRes = await Promise.all(
  entry.data.categories?.map(async (cat) => {
    const category = await getEntry('categories', cat.id);
    if (!category) {
      throw new Error(`Category not found: ${cat.id}`);
    }
    return category;
  }) ?? []
);

const glossary = await getCollection('glossary');
const filteredGlossary = glossary.filter((entry) => !entry.data.draft);
const glossaryLookup = filteredGlossary.reduce<Record<string, string>>(
  (lookup, entry) => {
    lookup[entry.data.title.toLowerCase()] = entry.id;

    // Add aliases to the lookup
    if (entry.data.aliases && Array.isArray(entry.data.aliases)) {
      entry.data.aliases.forEach((alias: string) => {
        lookup[alias.toLowerCase()] = entry.id;
      });
    }

    return lookup;
  },
  {}
);

const { headings, Content } = await render(entry);

const monthNames = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const displayDate = entry.data.lastUpdated || entry.data.date;
const [year, month] = displayDate.split('-');
const formattedDate = `${monthNames[parseInt(month, 10) - 1]} ${year}`;

const structuredData = {
  '@context': 'https://schema.org',
  '@type': 'BlogPosting',
  headline: entry.data.title,
  description: entry.data.excerpt || '',
  datePublished: entry.data.date || new Date().toISOString(),
  dateModified: displayDate,
  mainEntityOfPage: {
    '@type': 'WebPage',
    '@id': new URL(Astro.url.pathname, Astro.site).toString(),
  },
  author: {
    '@type': 'Person',
    name: 'Mark Levison',
  },
  publisher: {
    '@type': 'Organization',
    name: 'Agile Pain Relief',
    logo: {
      '@type': 'ImageObject',
      url: new URL('/logo.png', Astro.site).toString(),
    },
  },
  image: entry.data.coverImage
    ? new URL(entry.data.coverImage.src, Astro.site).toString()
    : undefined,
  keywords: entry.data.categories?.map((cat) => cat.id).join(', ') || '',
};

// Create structured data for breadcrumbs
const breadcrumbsStructuredData = {
  '@type': 'BreadcrumbList',
  itemListElement: [
    {
      '@type': 'ListItem',
      position: 1,
      name: 'Blog',
      item: new URL('/blog/', Astro.site).toString(),
    },
    {
      '@type': 'ListItem',
      position: 2,
      name: entry.data.title,
      item: new URL(Astro.url.pathname, Astro.site).toString(),
    },
  ],
};
