          <div
            class={clsx(
              'prose prose-strong:text-blue-900 prose-blue prose-a:text-orange-600 prose-a:hover:text-orange-700 prose-a:font-normal prose-blockquote:border-blue-200 prose-blockquote:py-0.5 prose-headings:scroll-mt-24 prose-ul:marker:text-blue-800 prose-ol:marker:text-blue-800 max-w-none transition-colors',
              'prose-table:border-collapse prose-table:w-full prose-thead:bg-blue-200 prose-table:bg-blue-50 prose-th:border prose-th:border-blue-200 prose-th:p-2 prose-th:text-left prose-td:border prose-td:rounded-md prose-td:border-blue-200 prose-td:p-2',
              'prose-table:overflow-x-auto prose-table:block prose-table:max-w-full'
            )}
            id="blog-content"
            data-glossary={JSON.stringify(glossaryLookup)}
          >
            <Content />
          </div>
          <div class="mt-8 block border-t-2 border-blue-200 pt-8 lg:hidden">
            {categoriesRes && <Categories categories={categoriesRes} />}
          </div>
          <Author />
        </article>
      </div>

      <aside class="relative hidden h-full pl-10 lg:block">
        <div class="sticky top-24 flex flex-col">
          {entry.data.categories && <Categories categories={categoriesRes} />}

          <div class="flex-co mt-10 flex">
            <LinkSidebar />
          </div>
        </div>
      </aside>
    </div>
    <ModalPopup attribution="blog" source={SignupSource.Blog} />
  </div>
</Layout>

<script>
  import { linkGlossaryTerms } from '@/utils/glossaryLookup';

  function initGlossaryLinks() {
    const contentElement = document.getElementById('blog-content');
    if (!contentElement) return;

    const glossaryData = contentElement.dataset.glossary;
    if (!glossaryData) return;

    const glossaryLookup = JSON.parse(glossaryData);
    const content = contentElement.innerHTML;
    contentElement.innerHTML = linkGlossaryTerms(content, glossaryLookup);
  }

  initGlossaryLinks();
</script>

