} from '@/components/ui/breadcrumb';

import { getCollection, getEntry, render } from 'astro:content';

export async function getStaticPaths() {
  const entries = await getCollection('glossary');

  const showDrafts = process.argv.includes('--drafts');

  const filteredEntries = showDrafts
    ? entries
    : entries.filter((entry) => !entry.data.draft);

  return filteredEntries.map((entry) => ({
    params: { id: entry.id },
  }));
}

const { id } = Astro.params;

const showDrafts = process.argv.includes('--drafts');
const allTerms = await getCollection('glossary');
const filteredTerms = showDrafts
  ? allTerms
  : allTerms.filter((term) => !term.data.draft);
const entry = await getEntry('glossary', id);
if (!entry) {
  return new Response(null, {
    status: 404,
    statusText: 'Not found',
  });
}

const relatedTerms = entry.data.relatedTerms
  ? await Promise.all(
      entry.data.relatedTerms.map(async (term: { id: string }) => {
        const relatedTerm = await getEntry('glossary', term.id);
        if (!relatedTerm) {
          throw new Error(`Related term not found: ${term.id}`);
        }
        return relatedTerm;
      })
    )
  : [];

const hasRelatedTerms = relatedTerms && relatedTerms.length > 0;

const { Content } = await render(entry);

const monthNames = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const displayDate = entry.data.lastUpdated || entry.data.date;
