  relatedTo:
    relatedTerms.length > 0
      ? relatedTerms.map((term) => ({
          '@type': 'DefinedTerm',
          name: term.data.title,
          url: new URL(`/glossary/${term.id}/`, Astro.site).toString(),
        }))
      : undefined,
};

// Create structured data for breadcrumbs
const breadcrumbsStructuredData = {
  '@type': 'BreadcrumbList',
  itemListElement: [
    {
      '@type': 'ListItem',
      position: 1,
      name: 'Glossary',
      item: new URL('/glossary/', Astro.site).toString(),
    },
    {
      '@type': 'ListItem',
      position: 2,
      name: entry.data.title,
      item: new URL(Astro.url.pathname, Astro.site).toString(),
    },
  ],
};
